const nilaiSiswa = [75, 80, 65, 90, 85];

// Nomor 1: Mengubah nilai kedua menjadi 88
nilaiSiswa[1] = 88;

// Nomor 2: Mengubah nilai ketiga menjadi 78
nilaiSiswa[2] = 78;

// Nomor 3: Tampilan nilai siswa setelah perubahan
console.log("Nilai Siswa:", nilaiSiswa);

// Nomor 4: Tampilan nilai pertama dan terakhir sesudah perubahan
console.log("Nilai Pertama:", nilaiSiswa[0]);
console.log("Nilai Terakhir:", nilaiSiswa[nilaiSiswa.length - 1]);